# Essential imports (guaranteed to be available)
import os
import torch
import torch.nn as nn
import torch.nn.functional as F
import torch.optim as optim
from dataset import get_dataloader
import json
from tqdm import tqdm
import numpy as np
from sklearn.metrics import roc_auc_score


# Constants
DATA_DIR = "/mnt/disks/data/birdclef"
METADATA_FILE = os.path.join(DATA_DIR, "train.csv")
NUM_CLASSES = 206  # Number of bird species for multi-label classification

# Hyperparameters based on iteration number (for demonstration, let's assume iteration 1)
iteration = 1
batch_size = 16 if iteration % 3 == 1 else (8 if iteration % 3 == 0 else 32)
learning_rate = 0.0001 if iteration % 3 == 1 else (0.001 if iteration % 3 == 0 else 0.00001)
num_conv_layers = 3 if iteration % 3 == 1 else (2 if iteration % 3 == 0 else 4)
dropout_rate = 0.2

# DataLoader
train_loader = get_dataloader(DATA_DIR, METADATA_FILE, batch_size=batch_size)

# Model Definition
class BirdCLEFModel(nn.Module):
    def __init__(self, num_classes=NUM_CLASSES):
        super(BirdCLEFModel, self).__init__()
        conv_layers = []
        channels = [1] + [32, 64, 128, 256][:num_conv_layers]
        
        for in_channels, out_channels in zip(channels[:-1], channels[1:]):
            conv_layers.append(nn.Conv2d(in_channels, out_channels, kernel_size=3, padding=1))
            conv_layers.append(nn.BatchNorm2d(out_channels))
            conv_layers.append(nn.ReLU())
            
        self.conv_layers = nn.Sequential(*conv_layers)
        self.pool = nn.AdaptiveAvgPool2d((1, 1))
        
        classifier = [nn.Linear(channels[-1], 512), nn.ReLU(), nn.Dropout(dropout_rate)]
        classifier.append(nn.Linear(512, num_classes))
        self.classifier = nn.Sequential(*classifier)
    
    def forward(self, x):
        x = self.conv_layers(x)
        x = self.pool(x).view(x.size(0), -1)
        return torch.sigmoid(self.classifier(x))

# Initialize model, loss function, optimizer
model = BirdCLEFModel(num_classes=NUM_CLASSES)
criterion = nn.BCELoss()
optimizer = optim.Adam(model.parameters(), lr=learning_rate)

# Training Loop
device = torch.device('cuda' if torch.cuda.is_available() else 'cpu')
model.to(device)
epochs = 6

for epoch in range(epochs):
    model.train()
    total_loss = 0.0
    
    for batch, (inputs, labels) in enumerate(train_loader):
        inputs, labels = inputs.to(device), labels.to(device)
        
        optimizer.zero_grad()
        outputs = model(inputs)
        loss = criterion(outputs, labels.float())
        loss.backward()
        optimizer.step()
        
        total_loss += loss.item()
        torch.cuda.empty_cache()  # Clear GPU memory
        
        if batch % 10 == 0:
            print(f"Epoch {epoch+1}/{epochs}, Batch {batch}, Loss: {loss.item():.4f}")
    
    avg_train_loss = total_loss / len(train_loader)
    print(f"Epoch {epoch+1} finished, Average Train Loss: {avg_train_loss:.4f}")

# Validation
model.eval()
all_preds = []
all_labels = []

with torch.no_grad():
    for inputs, labels in train_loader:
        inputs, labels = inputs.to(device), labels.to(device)
        outputs = model(inputs)
        all_preds.append(outputs.cpu().numpy())
        all_labels.append(labels.cpu().numpy())


all_preds = np.concatenate(all_preds)
all_labels = np.concatenate(all_labels)

final_auc = roc_auc_score(all_labels, all_preds, average='weighted')
print(f"Validation AUC: {final_auc:.4f}")

# Save Metrics and Model
metrics = {
    "final_train_loss": avg_train_loss,
    "final_auc": final_auc,
    "num_params": sum(p.numel() for p in model.parameters()),
    "epochs_trained": epochs,
    "batch_size": batch_size,
    "training_samples": len(train_loader.dataset),
    "eval_samples": len(train_loader.dataset)
}

with open('metrics.json', 'w') as f:
    json.dump(metrics, f)

print("METRICS: " + json.dumps(metrics))

torch.save(model.state_dict(), 'model.pt')